import org.apache.http.HttpEntity
import org.apache.http.HttpHeaders
import org.apache.http.HttpResponse
import org.apache.http.client.methods.HttpGet
import org.apache.http.conn.ssl.NoopHostnameVerifier
import org.apache.http.conn.ssl.SSLConnectionSocketFactory
import org.apache.http.impl.client.CloseableHttpClient
import org.apache.http.impl.client.HttpClients
import org.apache.http.util.EntityUtils
import groovy.json.JsonSlurper
import javax.net.ssl.SSLContext
import javax.net.ssl.TrustManager
import javax.net.ssl.X509TrustManager
import java.security.cert.X509Certificate
import com.santaba.agent.util.script.ScriptCache

// Variables
def model = hostProps.get("auto.entphysical.modelname")

def cache = ScriptCache.getCache()
def newToken = false
def key = "${model}.firmwareCheck"
def tokenValue = cache.get(key)

if (!tokenValue) {
    def response = FirmwareCheck()
    if (!response.contains("Error")) {
        token = response
        cache.set(key, token, 172800000)
        newToken = true
        response += "&obtained=API"
        println(response)
    }
} else {
    tokenValue += "&obtained=CACHE"
    println("${tokenValue}")
}

def FirmwareCheck() {
    def hostname = hostProps.get("system.hostname")
    def token = hostProps.get("cisco.token.key")
    def sysinfo = hostProps.get("system.sysinfo")
    def model = hostProps.get("auto.entphysical.modelname")
    //Firmware Formatting
    
    def versionNameRegex = /\[(.*?)\]/
    def versionNumberRegex = /Version (\d+\.\d+\.\w+)/
    def versionBracketRegex1 = /Version (\d+)\.(\d+)\((\d+)\)(S\w+)/
    def versionBracketRegex2 = /Version (\d+)\.(\d+)\((\d+)\)(E\w+)/
    def versionBracketRegex3 = /NX-OS.*Version (\d+\.\d+.*), RELEASE/
    
    def versionNameMatcher = (sysinfo =~ versionNameRegex)
    def versionNumberMatcher = (sysinfo =~ versionNumberRegex)
    def versionBracket1Matcher = (sysinfo =~ versionBracketRegex1)
    def versionBracket2Matcher = (sysinfo =~ versionBracketRegex2)
    def versionBracket3Matcher = (sysinfo =~ versionBracketRegex3)
    
    def versionName = versionNameMatcher.find() ? versionNameMatcher.group(1) : null
    def versionNumber1 = versionNumberMatcher.find() ? versionNumberMatcher.group(1) : null
    def versionNumber2 = versionBracket1Matcher.find() ? versionBracket1Matcher.group(1) : null
    def versionNumber3 = versionBracket2Matcher.find() ? versionBracket2Matcher.group(1) : null
    def versionNumber4 = versionBracket3Matcher.find() ? versionBracket3Matcher.group(1) : null
    
    def formattedVersion = "${versionNumber1}"
    
    if (versionName && versionNumber1){
        formattedVersion = "$versionName-$versionNumber1"
    }
    if (versionNumber2){
        formattedVersion = "${versionBracket1Matcher[0][1]}.${versionBracket1Matcher[0][2]}.${versionBracket1Matcher[0][3]}-${versionBracket1Matcher[0][4]}"
    }
    if (versionNumber3){
        formattedVersion = "${versionBracket2Matcher[0][1]}.${versionBracket2Matcher[0][2]}.${versionBracket2Matcher[0][3]}${versionBracket2Matcher[0][4]}"
    }
    if (versionNumber4){
        formattedVersion = versionNumber4
    }
    
    // API Request
    
    def apiEndpoint = "https://apix.cisco.com/software/suggestion/v2/suggestions/compatible/productId/${model}?currentRelease=${formattedVersion}"
    
    // Create a custom SSL context that skips certificate validation
    def trustAllCerts = [
        new X509TrustManager() {
            public void checkClientTrusted(X509Certificate[] x509Certificates, String s) {}
            public void checkServerTrusted(X509Certificate[] x509Certificates, String s) {}
            public X509Certificate[] getAcceptedIssuers() { null }
        }
    ] as TrustManager[]
    
    def sslContext = SSLContext.getInstance("TLS")
    sslContext.init(null, trustAllCerts, null)
    
    // Create a socket factory with a bypassed hostname verification
    def socketFactory = new SSLConnectionSocketFactory(sslContext, NoopHostnameVerifier.INSTANCE)
    
    // Create an HTTP client with the custom SSL context and socket factory
    def httpClient = HttpClients.custom().setSSLSocketFactory(socketFactory).build()
    
    
    // Create an HTTP GET request to retrieve system status
    def httpGet = new HttpGet(apiEndpoint)
    
    // Set Headers
    httpGet.setHeader(HttpHeaders.AUTHORIZATION, "Bearer ${token}")
    
        
    try {
        // Execute the request and retrieve the response
        def response = httpClient.execute(httpGet)
        
        // Extract the response entity
        def entity = response.getEntity()
        
        
        // Retry attempts for rate limiting
        def maxAttempts = 3
        def attempt = 1
    
        // Check if the request was successful (status code 200)
        while (attempt <= maxAttempts) {    
            if (response.getStatusLine().getStatusCode() == 200) {
                // Parse the response entity as JSON
                def responseBody = EntityUtils.toString(entity)
                def jsonSlurper = new JsonSlurper()
                def data = jsonSlurper.parseText(responseBody)
                
                def suggestedRelease = data.suggestions[0].relDispName
                def releaseDate = data.suggestions[0].releaseDate
                
                if (suggestedRelease) {
                    return "0##${suggestedRelease}##Suggested Release####auto.nd.suggested_release=${suggestedRelease}&auto.nd.current_release=${formattedVersion}&auto.nd.suggested_releaseDate=${releaseDate}"
                } else {
                    def error = "Unknown Error"
                    if (data.suggestions[0].errorDetailsResponse){
                        error = data.suggestions[0].errorDetailsResponse.errorDescription
                    }
                    return "Error = ${error}"
                }
                break
            } else {
                Thread.sleep(5000*attempt)
                    attempt++
            }
        }
    } finally {
        // Close the HTTP client and release any system resources
        httpClient.close()
    }
}
return 0

