import java.text.SimpleDateFormat
import java.util.Date

def releaseDate = instanceProps.get("auto.nd.suggested_releaseDate")

def dateFormat = new SimpleDateFormat("dd-MMM-yyyy")
def todaysDate = dateFormat.format(new Date()) // Today's date

def date1 = dateFormat.parse(releaseDate)
def date2 = dateFormat.parse(todaysDate)

// Calculate the difference in days
def differenceInMillis = date2.time - date1.time
def differenceInDays = differenceInMillis / (1000 * 60 * 60 * 24)

println("DaysSinceRelease=${differenceInDays}")

def suggestedRelease = instanceProps.get("auto.nd.suggested_release")
def currentRelease = instanceProps.get("auto.nd.current_release")

if(suggestedRelease==currentRelease){
    println("SameRelease=1")
} else {
    println("SameRelease=0")
}
